    float angle = static_cast<float>(tapIndex) * tau<float>() / 8.0f + static_cast<float>(ring) * 0.4f;
    return Vector2Of<float>(cosine(angle), sine(angle)) * static_cast<float>(ring) * radius * texel / 3.0f;
