/// Tags: kuwahara, quadrant, window sign
/// Node: inside kuwahara
inline Vector2Of<float> kuwaharaQuadrantSign(int quadrant) {
    return Vector2Of<float>(quadrant % 2 == 0 ? 1.0f : -1.0f, quadrant < 2 ? 1.0f : -1.0f);
}

